import { Scene, TextureAtlas, AnimatedSprite } from "retiam";

const scene = new Scene({ canvas });

// 1. Asynchronously load packed sprite sheet and JSON manifest
const atlas = await TextureAtlas.load("/assets/character.png", "/assets/character.json");

// 2. Instantiate animated sprite playing at 24 FPS
const walkCycle = new AnimatedSprite(atlas, "walk_", 24);
walkCycle.transform.scale = 2.0;
walkCycle.transform.position = [-3, 0, 0];
scene.add(walkCycle);

// 3. Play / Pause / Seek frame controls
walkCycle.play();
